(function(){
'use strict';
const data=window.STAGE_DATA,M=window.StageModel,$=id=>document.getElementById(id),week=['日','一','二','三','四','五','六'];
const today=M.taipeiToday(),base=M.parseDate(today>=data.start&&today<=data.end?today:data.start);
const state={year:base.getFullYear(),month:base.getMonth(),selected:M.dateKey(base),region:'all',city:M.defaultCity,format:'all',query:'',view:'programme',limit:12};
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shortDate=s=>{const d=M.parseDate(s);return `${d.getMonth()+1} 月 ${d.getDate()} 日`};
const weekday=s=>'週'+week[M.parseDate(s).getDay()];
function dateSelect(key,scroll=false){state.selected=key;state.limit=12;const d=M.parseDate(key);state.year=d.getFullYear();state.month=d.getMonth();render();if(scroll&&window.matchMedia('(max-width:760px)').matches)document.querySelector('.day-panel').scrollIntoView({behavior:'smooth',block:'start'})}
function resetFilters(){state.limit=12;state.region='all';state.city='all';state.format='all';$('show-format').value='all';state.query='';$('search').value='';render()}
function renderFilters(){const counts=Object.keys(M.regions).reduce((o,r)=>({...o,[r]:M.sessions(data,{region:r}).length}),{});$('regions').innerHTML=[['all','全台'],...Object.entries(M.regions)].map(([key,label])=>`<button class="region-button ${state.region===key?'active':''}" data-region="${key}" aria-pressed="${state.region===key}">${label}<small>${key==='all'?M.sessions(data).length:counts[key]}</small></button>`).join('');$('regions').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.region=b.dataset.region;state.city='all';state.limit=12;render()}));const cities=[...new Set(data.productions.filter(p=>state.region==='all'||p.region===state.region).map(p=>p.city))].sort((a,b)=>a.localeCompare(b,'zh-Hant'));$('city-filter').innerHTML='<option value="all">所有城市</option>'+cities.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('city-filter').value=state.city;}
function renderCalendar(list){$('month-label').textContent=`${state.year} 年 ${state.month+1} 月`;$('month-en').textContent=new Intl.DateTimeFormat('en',{month:'long'}).format(new Date(state.year,state.month,1)).toUpperCase();const first=`${state.year}-${M.pad(state.month+1)}-01`,last=M.dateKey(new Date(state.year,state.month+1,0));$('month-note').textContent=last<data.start||first>data.end?`此月份不在收錄期間內。可回到 ${data.start} 至 ${data.end} 查看。`:first<=data.start&&last>=data.start?`${shortDate(data.start)} 起為本次收錄範圍。`:first<=data.end&&last>=data.end?`本次收錄至 ${shortDate(data.end)}。`:'';$('calendar').innerHTML=M.monthCells(state.year,state.month).map(c=>{const items=list.filter(s=>s.date===c.key),rs=[...new Set(items.map(s=>s.production.region))];return `<button class="day ${c.inMonth?'':'other'} ${c.key===state.selected?'selected':''} ${c.key===today?'today':''} ${c.key<data.start||c.key>data.end?'outside':''}" data-date="${c.key}" aria-label="${c.key}，${items.length?'已收錄 '+items.length+' 場':'尚未收錄場次'}${c.key===today?'，今天':''}" aria-pressed="${c.key===state.selected}"><span class="day-number">${c.day}</span><span class="day-dots" aria-hidden="true">${rs.map(r=>`<i class="dot ${r}"></i>`).join('')}${items.length?`<span class="day-total">${items.length}</span>`:''}</span></button>`}).join('');$('calendar').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>dateSelect(b.dataset.date)));$('jump-date').value=state.selected;}
function ticketDetails(p){const t=(window.STAGE_TICKETS||{})[p.id];if(!t)return `<details class="ticket-details"><summary><span class="ticket-info-icon" aria-hidden="true">i</span> 售票／早鳥資訊 <span class="ticket-chevron" aria-hidden="true">＋</span></summary><div class="ticket-content"><p>尚未核對此場次的開賣與優惠公告，請查看官方售票頁。</p></div></details>`;const model=window.TicketModel;return `<details class="ticket-details"><summary><span class="ticket-info-icon" aria-hidden="true">i</span> 售票／早鳥資訊 <span class="ticket-chevron" aria-hidden="true">＋</span></summary><div class="ticket-content"><dl><dt>公告開賣時間</dt><dd>${esc(t.onSaleText||'官方頁面尚未確認開賣日期與時間。')}</dd></dl>${t.saleStatusText?`<p class="ticket-status-note">${esc(t.saleStatusText)}</p>`:''}<h5>早鳥／預售方案</h5>${t.earlyBird&&t.earlyBird.length?t.earlyBird.map(o=>{const status=model.offerState(o);return `<div class="ticket-offer ${status}"><div class="offer-heading"><strong>${esc(o.label||'早鳥方案')}</strong><span class="offer-status ${status}">${esc(model.labels[status])}</span></div><p>${esc(o.window||'優惠期間未確認')}</p>${o.discount?`<p class="offer-discount">${esc(o.discount)}</p>`:''}${o.conditions?`<p>${esc(o.conditions)}</p>`:''}</div>`}).join(''):'<p>官方頁面未確認早鳥方案；不代表沒有其他優惠。</p>'}${t.notes?`<p class="ticket-caveat">${esc(t.notes)}</p>`:''}<p class="ticket-caveat">僅整理公告，不提供即時餘票。優惠資格、期限及可用場次，請以結帳頁與主辦公告為準。</p><a class="ticket-booking" href="${esc(t.bookingUrl||p.ticketUrl||p.sourceUrl)}" target="_blank" rel="noopener noreferrer">前往官方售票頁 ↗<span class="sr-only">（另開分頁）</span></a><div class="ticket-sources"><p>票務核對：${esc(t.checkedAt||data.checkedAt)} · 台灣時間</p>${(t.sources||[]).map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ↗</a>`).join('')}</div></div></details>`;}
function eventCard(g){const p=g.production;return `<article class="event-card"><div class="event-category"><span class="event-city"><i class="dot ${p.region}"></i>${esc(p.city)} · ${M.regions[p.region]}</span><span>${esc(p.category||'音樂劇')}</span></div><h4>${esc(p.title)}</h4>${p.subtitle?`<p class="subtitle">${esc(p.subtitle)}</p>`:''}<p class="event-meta">${esc(p.venue)}</p><div class="time-chips" aria-label="演出時間">${g.times.map(t=>`<span class="time-chip">${esc(t)}</span>`).join('')}</div><p class="event-summary">${esc(p.summary)}</p>${p.notes?`<p class="event-notice">${esc(p.notes)}</p>`:''}${ticketDetails(p)}<a class="official-link" href="${esc(p.ticketUrl||p.sourceUrl)}" target="_blank" rel="noopener noreferrer">官方節目與購票 <span aria-hidden="true">↗</span></a><p class="verified">官方場次核對 ${esc(p.checkedAt||data.checkedAt)} · 台灣時間</p></article>`}
function renderDay(list){const allForDay=M.sessions(data).filter(s=>s.date===state.selected),forDay=list.filter(s=>s.date===state.selected);$('selected-label').textContent=shortDate(state.selected);$('selected-weekday').textContent=weekday(state.selected);$('selected-eyebrow').textContent=state.selected===today?"TODAY'S PROGRAMME":"THE DAY'S PROGRAMME";$('day-count').textContent=forDay.length?`已收錄 ${forDay.length} 場 · ${new Set(forDay.map(s=>s.production.id)).size} 部作品`:'此條件下尚無已收錄場次';if(forDay.length){$('day-events').innerHTML=M.groupSessions(forDay).map(eventCard).join('');return}const outside=state.selected<data.start||state.selected>data.end,filtered=allForDay.length>0;const next=list.find(s=>s.date>=state.selected)||list[0];$('day-events').innerHTML=`<div class="empty-day"><span class="empty-symbol" aria-hidden="true">◌</span><h4>${outside?'這一天，不在樣本期間內':filtered?'換個地方，看看其他舞台':'這一天，還沒有收錄場次'}</h4><p>${outside?`收錄期間為 ${data.start} 至 ${data.end}。`:filtered?'當天有其他地區或關鍵字條件外的演出，可以清除篩選查看。':'這不是「沒有演出」的意思。先逛逛已確認的日期，找到下一個值得期待的晚上。'}</p>${filtered?'<button id="clear-day">清除篩選</button>':next?`<button id="next-date">看 ${shortDate(next.date)} 的演出 <span aria-hidden="true">↗</span></button>`:''}</div>`;if($('clear-day'))$('clear-day').addEventListener('click',resetFilters);if($('next-date'))$('next-date').addEventListener('click',()=>dateSelect(next.date));}
function renderUpcoming(list){const anchor=state.selected<data.start?data.start:state.selected;const groups=M.groupSessions(list.filter(s=>s.date>=anchor)).slice(0,3);$('upcoming-summary').textContent=`從 ${shortDate(anchor)} 起 · 依目前篩選`;if(!groups.length){$('upcoming-list').innerHTML=`<p class="no-results">接下來尚無符合條件的已收錄場次。<button class="clear-button" id="reset-upcoming">查看全部樣本</button></p>`;$('reset-upcoming').addEventListener('click',()=>{resetFilters();dateSelect(data.start)});return}$('upcoming-list').innerHTML=groups.map(g=>{const d=M.parseDate(g.date);return `<button class="upcoming-card" data-date="${g.date}" aria-label="查看 ${g.date} ${esc(g.production.title)}"><span class="mini-date"><small>${d.getMonth()+1} 月</small><strong>${d.getDate()}</strong><em>${weekday(g.date)}</em></span><span class="upcoming-info"><small>${esc(g.production.city)} · ${g.times.join(' / ')}</small><h4>${esc(g.production.title)}</h4></span><span class="upcoming-arrow" aria-hidden="true">↗</span></button>`}).join('');$('upcoming-list').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{dateSelect(b.dataset.date,true);if(!window.matchMedia('(max-width:760px)').matches)document.querySelector('.calendar-layout').scrollIntoView({behavior:'smooth',block:'start'})}));}

function programmeItem(g){const p=g.production,alert=M.hasImportantNotice(p);return `<article class="programme-item"><div class="programme-identity"><p class="programme-category">${esc(p.category||'音樂劇')} · ${esc(p.city)}</p><h3>${esc(p.title)}</h3></div><p class="programme-venue"><strong>${g.times.map(esc).join(' ／ ')}</strong><span>${esc(p.venue)}</span></p><a class="programme-booking" href="${esc(p.ticketUrl||p.sourceUrl)}" target="_blank" rel="noopener noreferrer">官方購票 ↗<span class="sr-only">（${esc(p.title)}，另開分頁）</span></a>${alert?`<p class="programme-alert">${esc(p.notes)}</p>`:''}<div class="programme-disclosures"><details class="programme-story"><summary>節目介紹<span aria-hidden="true">＋</span></summary><div>${p.subtitle?`<p class="programme-subtitle">${esc(p.subtitle)}</p>`:''}<p class="programme-description">${esc(p.summary)}</p>${p.notes&&!alert?`<p class="programme-notice">${esc(p.notes)}</p>`:''}<p class="programme-checked">場次核對 ${esc(p.checkedAt||data.checkedAt)} · <a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">官方節目來源 ↗</a></p></div></details>${ticketDetails(p)}</div></article>`}
function renderMonthIndex(list){const months=[],last=data.end.slice(0,7);let cursor=M.parseDate(data.start);cursor.setDate(1);while(M.dateKey(cursor).slice(0,7)<=last){const key=M.dateKey(cursor).slice(0,7),count=list.filter(s=>s.date.startsWith(key)).length;months.push(`<button data-month="${key}" aria-label="從 ${cursor.getFullYear()} 年 ${cursor.getMonth()+1} 月開始，已收錄 ${count} 場" aria-pressed="${state.selected.slice(0,7)===key}"><span>${M.pad(cursor.getMonth()+1)}<small>月</small></span><em>${cursor.getFullYear()}</em><small>${count} 場</small></button>`);cursor.setMonth(cursor.getMonth()+1)}$('month-index').innerHTML='<p>從月份開始</p>'+months.join('');$('month-index').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.month;dateSelect(key+'-01'<data.start?data.start:key+'-01');$('month-index').querySelector(`[data-month="${key}"]`)?.focus()}))}
function renderProgramme(list){const anchor=state.selected<data.start?data.start:state.selected,upcoming=list.filter(s=>s.date>=anchor),days=[...new Set(upcoming.map(s=>s.date))],visible=days.slice(0,state.limit);$('programme-start').value=state.selected;$('programme-count').textContent=`此條件下 ${upcoming.length} 場 · ${new Set(upcoming.map(s=>s.production.productionId)).size} 部作品`;$('programme-list').innerHTML=visible.length?visible.map(date=>{const d=M.parseDate(date);return `<section class="programme-day" aria-label="${date} ${weekday(date)}"><header class="programme-date"><time datetime="${date}"><span>${M.pad(d.getMonth()+1)}.</span><strong>${M.pad(d.getDate())}</strong></time><span>${weekday(date)}</span><small>${d.getFullYear()}</small></header><div class="programme-entries">${M.groupSessions(upcoming.filter(s=>s.date===date)).map(programmeItem).join('')}</div></section>`}).join(''):'<div class="programme-empty"><h3>這個條件下，還沒有收錄節目。</h3><p>可以切換城市、日期或關鍵字；未收錄不代表沒有演出。</p></div>';$('programme-more').hidden=visible.length>=days.length;$('programme-more').textContent=`展開更多日期（尚有 ${Math.max(0,days.length-visible.length)} 天）`;}
function renderView(){const programme=state.view==='programme';$('programme-view').hidden=!programme;$('calendar-view').hidden=programme;$('view-programme').setAttribute('aria-pressed',String(programme));$('view-calendar').setAttribute('aria-pressed',String(!programme));$('hero-title').textContent=state.city==='臺北市'?'臺北，最近有什麼戲？':state.city!=='all'?`${state.city}，最近有什麼戲？`:state.region!=='all'?`${M.regions[state.region]}，最近有什麼戲？`:'接下來，有什麼戲？';}

function renderSources(){$('source-list').innerHTML=data.productions.map(p=>`<div class="source-item"><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} · ${esc(p.sourceName)} ↗</a><p><strong>${esc(p.city)} · ${esc(p.venue)}</strong></p><p>${p.sessions.map(s=>`${s.date} ${s.time}`).join(' ／ ')}</p>${p.timingSource&&p.timingSource!==p.sourceUrl?`<a href="${esc(p.timingSource)}" target="_blank" rel="noopener noreferrer">場次時間核對來源 ↗</a>`:''}<p>核對日：${esc(p.checkedAt||data.checkedAt)}。${esc(p.notes||'')}</p></div>`).join('')}
function render(){const list=M.sessions(data,state);renderFilters();renderCalendar(list);renderDay(list);renderUpcoming(list);renderProgramme(list);renderMonthIndex(list);renderView();$('coverage-count').textContent=`全站收錄 ${new Set(data.productions.map(p=>p.productionId)).size} 部作品 · ${M.sessions(data).length} 場已核對場次`}
const narrow=window.matchMedia('(max-width:960px)');$('filter-drawer').open=!narrow.matches;narrow.addEventListener?.('change',e=>{$('filter-drawer').open=!e.matches});
$('view-programme').addEventListener('click',()=>{state.view='programme';renderView()});$('view-calendar').addEventListener('click',()=>{state.view='calendar';renderView()});$('programme-start').addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))dateSelect(e.target.value)});$('programme-today').addEventListener('click',()=>dateSelect(M.taipeiToday()));$('programme-more').addEventListener('click',()=>{state.limit+=12;renderProgramme(M.sessions(data,state))});
$('show-format').addEventListener('change',e=>{state.format=e.target.value;state.limit=12;render()});$('city-filter').addEventListener('change',e=>{state.city=e.target.value;state.limit=12;render()});$('search').addEventListener('input',e=>{state.query=e.target.value;state.limit=12;render()});$('today').addEventListener('click',()=>dateSelect(M.taipeiToday()));$('jump-date').addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))dateSelect(e.target.value)});['prev-month','next-month'].forEach((id,i)=>$(id).addEventListener('click',()=>{const d=new Date(state.year,state.month+(i?1:-1),1,12);state.year=d.getFullYear();state.month=d.getMonth();render()}));if($('sample-range'))$('sample-range').textContent=`${data.start.replace(/-/g,'.')} — ${data.end.replace(/-/g,'.')}`;renderSources();render();
})();
